INPUT_DOWN_ID = "cabinet-input-down"
INPUT_LEFT_ID = "cabinet-input-left"
INPUT_RIGHT_ID = "cabinet-input-right"
INPUT_FIRE_ID = "cabinet-input-fire"
PILOT_DIR_ID = "cabinet-pilot-dir"
