    def switch_costume(self, costume: str) -> str:
        menu = self.add(
            "looks_costume", fields={"COSTUME": [costume, None]}, shadow=True
        )
        block_id = self.add(
            "looks_switchcostumeto", inputs={"COSTUME": [1, menu]}
        )
        self.blocks[menu]["parent"] = block_id
        return block_id

    def switch_costume_expr(self, reporter_id: str, shadow_costume: str = "digit/0") -> str:
        # Like switch_costume(), but the costume NAME is computed at runtime (a reporter,
        # e.g. a joined "digit/<n>" string). The costume input is a MENU input, so the
        # reporter must OBSCURE a costume-menu shadow ([3, reporter, shadow]) — a bare
        # [2, reporter] leaves the menu input unread and the switch never happens.
        menu = self.add(
            "looks_costume", fields={"COSTUME": [shadow_costume, None]}, shadow=True
        )
        block_id = self.add(
            "looks_switchcostumeto", inputs={"COSTUME": [3, reporter_id, menu]}
        )
        self.blocks[reporter_id]["parent"] = block_id
        self.blocks[menu]["parent"] = block_id
        return block_id

    def set_effect(self, effect: str, value: Any) -> str:
        # `looks_seteffectto`: EFFECT is a dropdown FIELD (e.g. "COLOR"); VALUE is a numeric input that
        # accepts a literal spec (number()/variable()) or a nested reporter's block id (str), wired like the
        # arithmetic operands above.
        block_id = self.add("looks_seteffectto", fields={"EFFECT": [effect, None]})
        if isinstance(value, str):
            self.blocks[block_id]["inputs"] = {"VALUE": [2, value]}
            self.blocks[value]["parent"] = block_id
        else:
            self.blocks[block_id]["inputs"] = {"VALUE": value}
        return block_id

    def clear_graphic_effects(self) -> str:
        return self.add("looks_cleargraphiceffects")

